USE god2_game;

CREATE TABLE IF NOT EXISTS god2_research.xjz_npc_shop_slot_candidates (
    source_slot_id INT NOT NULL,
    shop_list_id INT NOT NULL,
    shop_group INT NOT NULL,
    slot_index INT NOT NULL,
    client_item_id INT NOT NULL,
    item_name_zh_tw VARCHAR(200) NULL,
    item_prefix VARCHAR(32) NULL,
    item_category_kind VARCHAR(64) NOT NULL,
    formal_item_id BIGINT NULL,
    formal_item_code VARCHAR(100) NULL,
    formal_item_name_zh_tw VARCHAR(200) NULL,
    weapon_match TINYINT(1) NOT NULL,
    armor_match TINYINT(1) NOT NULL,
    combat_pet_item_match TINYINT(1) NOT NULL,
    item_template_match TINYINT(1) NOT NULL,
    raw_source VARCHAR(256) NOT NULL,
    raw_line INT NULL,
    evidence_status VARCHAR(64) NOT NULL,
    packet_evidence_boundary TINYINT(1) NOT NULL,
    source_pack_id VARCHAR(96) NOT NULL,
    promoted_to_formal_shop TINYINT(1) NOT NULL DEFAULT 0,
    blocked_reason_zh_tw VARCHAR(512) NULL,
    created_at_utc DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),
    PRIMARY KEY (source_pack_id, shop_list_id, slot_index, client_item_id),
    KEY idx_xjz_npc_shop_slot_client_item_id (client_item_id),
    KEY idx_xjz_npc_shop_slot_formal_item_id (formal_item_id),
    KEY idx_xjz_npc_shop_slot_shop_list (shop_list_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS god2_research.xjz_npc_shop_slot_candidate_summary (
    source_pack_id VARCHAR(96) NOT NULL,
    item_category_kind VARCHAR(64) NOT NULL,
    slot_count INT NOT NULL,
    distinct_client_item_count INT NOT NULL,
    linked_formal_item_count INT NOT NULL,
    packet_evidence_boundary TINYINT(1) NOT NULL,
    blocked_reason_zh_tw VARCHAR(512) NOT NULL,
    PRIMARY KEY (source_pack_id, item_category_kind)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TEMPORARY TABLE xjz_npc_shop_slot_stage (
    slot_id INT NOT NULL PRIMARY KEY,
    shop_list_id INT NOT NULL,
    shop_group INT NOT NULL,
    slot_index INT NOT NULL,
    item_id INT NOT NULL,
    item_name_zh_tw VARCHAR(200) NULL,
    item_prefix VARCHAR(32) NULL,
    item_category_kind VARCHAR(64) NOT NULL,
    weapon_match INT NOT NULL,
    armor_match INT NOT NULL,
    combat_pet_item_match INT NOT NULL,
    item_template_match INT NOT NULL,
    raw_source VARCHAR(256) NOT NULL,
    raw_line INT NULL,
    evidence_status VARCHAR(64) NOT NULL,
    packet_evidence_boundary INT NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DELETE FROM god2_research.xjz_npc_shop_slot_candidates
WHERE source_pack_id = 'XJZ-csharp-evidence-capture-pack-20260818';

    source_slot_id,
    shop_list_id,
    shop_group,
    slot_index,
    client_item_id,
    item_name_zh_tw,
    item_prefix,
    item_category_kind,
    formal_item_id,
    formal_item_code,
    formal_item_name_zh_tw,
    weapon_match,
    armor_match,
    combat_pet_item_match,
    item_template_match,
    raw_source,
    raw_line,
    evidence_status,
    packet_evidence_boundary,
    source_pack_id,
    promoted_to_formal_shop,
    blocked_reason_zh_tw
)
SELECT
    s.slot_id,
    s.shop_list_id,
    s.shop_group,
    s.slot_index,
    s.item_id,
    COALESCE(i.name_zh_tw, s.item_name_zh_tw),
    s.item_prefix,
    s.item_category_kind,
    i.item_id,
    i.code,
    i.name_zh_tw,
    s.weapon_match,
    s.armor_match,
    s.combat_pet_item_match,
    s.item_template_match,
    s.raw_source,
    s.raw_line,
    s.evidence_status,
    s.packet_evidence_boundary,
    'XJZ-csharp-evidence-capture-pack-20260818',
    0,
    '已有客戶端商店格候選；正式 NPC 綁定與價格公式仍需官方封包或黑箱測試。'
FROM xjz_npc_shop_slot_stage s
LEFT JOIN god2_game.items i
    ON i.client_item_id = s.item_id;

DELETE FROM god2_research.xjz_npc_shop_slot_candidate_summary
WHERE source_pack_id = 'XJZ-csharp-evidence-capture-pack-20260818';

    source_pack_id,
    item_category_kind,
    slot_count,
    distinct_client_item_count,
    linked_formal_item_count,
    packet_evidence_boundary,
    blocked_reason_zh_tw
)
SELECT
    'XJZ-csharp-evidence-capture-pack-20260818',
    item_category_kind,
    COUNT(*) AS slot_count,
    COUNT(DISTINCT client_item_id) AS distinct_client_item_count,
    COUNT(DISTINCT formal_item_id) AS linked_formal_item_count,
    1,
    'NPC 綁定與價格公式仍是封包邊界；候選資料先供服務端商店補齊使用。'
FROM god2_research.xjz_npc_shop_slot_candidates
WHERE source_pack_id = 'XJZ-csharp-evidence-capture-pack-20260818'
GROUP BY item_category_kind;

UPDATE god2_research.xjz_csharp_apply_queue
SET
    safe_apply_level_zh_tw = CONCAT(
        '已匯入商店格候選 ',
        (SELECT COUNT(*) FROM god2_research.xjz_npc_shop_slot_candidates WHERE source_pack_id = 'XJZ-csharp-evidence-capture-pack-20260818'),
        ' 筆，已對到正式道具 ',
        (SELECT COUNT(*) FROM god2_research.xjz_npc_shop_slot_candidates WHERE source_pack_id = 'XJZ-csharp-evidence-capture-pack-20260818' AND formal_item_id IS NOT NULL),
        ' 筆'
    ),
    next_server_action_zh_tw = '候選商店格已可供正式商店實裝比對；NPC 綁定與價格公式仍需官方封包或黑箱測試後再升正式。'
WHERE queue_key = 'npc_shop_slots';
